IF
DestroyedBy(_Chest,_,_,_)
AND
DB_FOR_ThayanCellar_AmbushStopped(0)
AND
DB_FOR_ThayanCellar_UndeadContainer(_Chest, _Undead)
AND
GetWorldTransformFromLocal(_Chest, 0.0, 0.0, 0.0, 0.0 ,-90.0, 0.0, _DestX, _Y, _DestZ, _RotX, _RotY, _RotZ)
AND
RealSum(_Y, 2.0, _DestY)
THEN
ToTransform(S_FOR_ThayG_SpawnHelper_86195bd5-840e-41f9-97cc-24cdfd30e3c9,_DestX, _DestY, _DestZ,0.0,_RotY,0.0);
TeleportTo(_Undead,S_FOR_ThayG_SpawnHelper_86195bd5-840e-41f9-97cc-24cdfd30e3c9,"", 0, 0, 0, 0, 1);
SetOnStage(_Undead,1);
RealtimeObjectTimerLaunch(_Undead,"FOR_ThayanCellar_SkeletonRise",250);
NOT DB_FOR_ThayanCellar_UndeadContainer(_Chest, _Undead);
DB_FOR_ThayanCellar_ActiveUndead((CHARACTER)_Undead);
PROC_FOR_ThayanCellar_TombCheck();
SetEntityEvent(_Undead, "FOR_ThayanCellar_SkeletonReleased_QuestUpdate");
